import{_ as o,o as a,c as s,a2 as r}from"./chunks/framework.D66Xq0Kv.js";const m=JSON.parse('{"title":"GitHub e previews","description":"","frontmatter":{},"headers":[],"relativePath":"pt-BR/guide/github.md","filePath":"pt-BR/guide/github.md"}'),i={name:"pt-BR/guide/github.md"};function t(n,e,u,p,l,d){return a(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="github-e-previews" tabindex="-1">GitHub e previews <a class="header-anchor" href="#github-e-previews" aria-label="Permalink to &quot;GitHub e previews&quot;">​</a></h1><h2 id="connecting" tabindex="-1">Conectando o GitHub <a class="header-anchor" href="#connecting" aria-label="Permalink to &quot;Conectando o GitHub {#connecting}&quot;">​</a></h2><p>Na primeira vez que você conecta o GitHub, o Orbit pede ao GitHub para criar um App para este servidor. Ao instalar, o GitHub pergunta onde (a sua conta ou uma das suas organizações), e o App só consegue ler os repositórios que você escolher ali.</p><ul><li><strong>Por que o App é público:</strong> o GitHub só instala um App privado na conta que o criou. Público só quer dizer que ele pode ser instalado em outro lugar. Qualquer pessoa vê a página dele, mas a chave fica no seu servidor, e o Orbit só usa a instalação confirmada pelo usuário do GitHub que conecta a partir do seu console.</li><li><strong>Pertencendo a uma organização:</strong> o Orbit pode criar o App em nome de uma organização, se a organização quiser tê-lo nas configurações dela.</li><li><strong>Nome e logo:</strong> o App se chama &quot;Orbit &lt;nome do servidor&gt;&quot;, o que você pode mudar antes de criá-lo; o GitHub exige um nome que nenhum outro App use. O GitHub só aceita logo pela página de configurações do App, então Configurações → Integrações oferece o logo do Orbit e o link para essa página.</li><li><strong>Uma instalação por vez:</strong> para ler os repositórios de outra conta, desconecte e conecte de novo, escolhendo essa conta.</li><li><strong>Endereços:</strong> o GitHub te devolve para o endereço que você usava ao criar o App, então crie-o a partir de <code>https://orbit.&lt;ip-do-servidor-com-traços&gt;.sslip.io</code> e não por um túnel SSH. Se depois você acessar o Orbit por outro endereço, atualize no GitHub a callback URL do App para <code>&lt;novo endereço&gt;/github/callback</code>.</li><li><strong>Onde fica a chave:</strong> a chave privada e os segredos do App ficam selados no cofre de segredos do Orbit e vão junto no <code>orbit backup</code>. Desconectar esquece a instalação mas mantém o App. Apagar o App no GitHub faz o Orbit criar um novo na próxima conexão.</li></ul><h2 id="push" tabindex="-1">Deploy a cada push <a class="header-anchor" href="#push" aria-label="Permalink to &quot;Deploy a cada push {#push}&quot;">​</a></h2><ul><li>O App envia cada push para <code>https://orbit.&lt;ip-do-servidor-com-traços&gt;.sslip.io/github/webhook</code>, assinado com um segredo que só o seu servidor conhece.</li><li>Um push na branch de uma aplicação publica aquele commit quando <strong>Publicar automaticamente</strong> está ligado nas configurações da aplicação. A mesma entrega duas vezes publica uma vez só.</li><li>Em Apps criados por versões mais antigas, ligue o evento <strong>Push</strong> no GitHub (Permissions &amp; events → Subscribe to events); Configurações → Integrações avisa enquanto ele estiver desligado.</li></ul><h2 id="previews" tabindex="-1">Previews de pull request <a class="header-anchor" href="#previews" aria-label="Permalink to &quot;Previews de pull request {#previews}&quot;">​</a></h2><p>Ligue os previews em <strong>Previews</strong> do projeto, ao lado dos ambientes, e escolha o ambiente que eles copiam e quantos podem rodar ao mesmo tempo (3 por padrão, no máximo 10).</p><p>Todo pull request aberto a partir de uma branch de um repositório que esse ambiente compila ganha um preview com o nome dele (<code>pr-12</code>):</p><ul><li>os serviços compilados daquele repositório, publicados a partir da branch do pull request, com as variáveis e segredos da origem;</li><li>cópias vazias dos bancos que esses serviços referenciam, sem backups, então um preview nunca lê nem escreve seus dados reais;</li><li>namespace e endereço gerado próprios (<code>&lt;serviço&gt;-pr-12-&lt;projeto&gt;.&lt;ip-do-servidor-com-traços&gt;.sslip.io</code>), ou <code>pr-12.&lt;domínio&gt;</code> quando os previews têm <a href="./cloudflare#previews">um domínio seu na Cloudflare</a>.</li></ul><p>Pushes na branch publicam o preview de novo. Fechar ou fazer merge do pull request remove o preview com os seus dados, e <strong>Remover</strong> faz o mesmo à mão.</p><ul><li><strong>Forks:</strong> pull requests de forks nunca ganham preview, então código de fora do repositório nunca roda nos seus servidores.</li><li><strong>O limite:</strong> depois dele, um pull request ganha o preview no próximo push, quando outro fechar. Desligar os previews mantém os abertos até os pull requests fecharem.</li><li><strong>Apps mais antigos:</strong> os previews precisam de <strong>Pull requests: read</strong> e do evento <strong>Pull request</strong>. Adicione os dois no GitHub (Permissions &amp; events) e aceite a nova permissão na instalação; a página de Previews avisa enquanto o evento faltar.</li></ul>',12)])])}const g=o(i,[["render",t]]);export{m as __pageData,g as default};
